(() => {
  /* page's own functions — if these are missing, the modules did not load */
  if (typeof turnResponse !== "function") throw new Error("turnResponse is not defined");
  if (typeof gvChipHtml !== "function") throw new Error("gvChipHtml is not defined");
  if (typeof gvAgents !== "function") throw new Error("gvAgents is not defined");
  /* a fresh profile shows the first-run interstitial over everything; dismiss
     it in memory only — no server settings write */
  if (window.S) S.onbDismissed = true;
  const onb = document.getElementById("onbHost");
  if (onb && onb.firstChild && typeof render === "function") render();
  /* THIS PAGE ONLY (isolated QA browser context): stop the live session stream.
     Its sync/changed/tick frames re-render #panes wholesale at arbitrary times,
     which wipes the injected demo turn between states and makes screenshots
     depend on whatever sessions happen to be active on the machine. The dummy
     keeps startSessionStream()'s reopen guard satisfied. */
  try {
    if (typeof _sessStream !== "undefined") {
      if (_sessStream && _sessStream.close) _sessStream.close();
      _sessStream = { readyState: 2, close() {} };
    }
  } catch (e) {}
  /* Freeze background re-renders (QA page only). On a panel with live sessions,
     transcript tailing schedules render() continuously and render() replaces
     #panes WHOLESALE — an injected demo turn is wiped within ~100ms of
     mounting. The original is kept as __qaRender for the states that need a
     real re-render (the pane fold); everything the states mount afterwards
     stays exactly where it was put. */
  if (!window.__qaRender && typeof render === "function") {
    window.__qaRender = render;
    render = () => {};
  }
  /* the demo turn, composed exactly as design/drive-app.mjs composes it */
  window.__qaTurn = () => {
    const raw = window.__qaRuns;
    if (!Array.isArray(raw) || !raw.length) throw new Error("window.__qaRuns missing — run.sh composes it from tests/fixtures/toolruns-fanout.json");
    S.thinkOpen = { demo: true };
    /* the fixture's clock is frozen in 2023; rebase onto now so RUNNING rows
       read like something an operator actually sees */
    const t0 = Date.now() - 9 * 60 * 1000;
    const base = raw[0].startedAt;
    const runs = raw.map((r) => Object.assign({}, r, {
      startedAt: t0 + (r.startedAt - base),
      endedAt: r.endedAt == null ? undefined : t0 + (r.endedAt - base),
    }));
    /* the captured fan-out contains no FAILURE; append one, clearly marked as
       demo composition, because the failure colouring is what is worth proving */
    runs.push({ id: "toolu_demo_fail", name: "Bash", summary: "bats cynefin.bats",
      running: false, ok: false, startedAt: t0 + 9000, endedAt: t0 + 80000 });
    return { uid: "demo", streaming: true,
      response: "Placement is migrated; lens is mid-rewrite; cynefin hit a golden-test drift.",
      tools: runs.map((r) => r.name), toolRuns: runs };
  };
  window.__qaHtml = (t) => '<div class="u md">Migrate all twelve engines to ledger schema v2.</div>'
    + gvChipHtml(t, 0) + turnResponse(t);
  /* visible copy in the real browse pane body; any app render() wipes it, so
     later states simply call this again */
  window.__qaFanout = () => {
    const t = window.__qaTurn();
    const pb = document.querySelector("#panes .pane.browse .pb") || document.querySelector("#panes .pane .pb");
    if (!pb) throw new Error("no expanded .pane .pb in the running panel");
    const wrap = document.createElement("div");
    wrap.className = "turn";
    wrap.innerHTML = window.__qaHtml(t);
    pb.innerHTML = "";
    pb.appendChild(wrap);
    return pb.querySelectorAll(".gv-agents button.trow").length;
  };
  /* offscreen probe rig: the SAME app-rendered markup kept mounted on <body>
     (render() never touches <body> children outside #panes), so the global
     contrast/focus rules keep their subjects in EVERY state — boot and
     collapsed-pane included. Offscreen, not display:none: computed styles and
     programmatic focus stay real */
  let probe = document.getElementById("qa-probe");
  if (!probe) {
    probe = document.createElement("div");
    probe.id = "qa-probe";
    probe.className = "pane";
    probe.style.cssText = "position:absolute;left:-9999px;top:0;width:900px";
    document.body.appendChild(probe);
  }
  probe.innerHTML = '<div class="pb"><div class="turn">' + window.__qaHtml(window.__qaTurn()) + "</div></div>";
  return probe.querySelectorAll(".gv-log .gv-ln").length;
})()

(() => {
  const bad = document.querySelector("#panes .gv-log .gv-ln.bad");
  if (!bad) throw new Error("the open step log with its failure line is not in the pane");
  bad.scrollIntoView({ block: "center" });
  return true;
})()

(() => {
  S.govOpen = { demo: true };
  window.__qaFanout();
  const p = document.querySelector("#panes .gv.gv-open .gv-panel");
  if (!p) throw new Error("the governance chip did not open");
  p.scrollIntoView({ block: "center" });
  return true;
})()

